final_design:
module TopModule (
    input clk,
    input d,
    output reg q
);
    reg q_pos, q_neg;

    always @(posedge clk) begin
        q_pos <= d;
    end

    always @(posedge (~clk)) begin
        q_neg <= d;
    end

    always @* begin
        q = clk ? q_pos : q_neg;
    end
endmodule

